import numpy as np

with open("flag_ct.txt", "rb") as f:
    data = f.read()

start = data.find(b'[')
end = data.rfind(b']') + 1
list_str = data[start:end].replace(b'np.complex128', b'complex')

ct = eval(list_str.decode('utf-8', errors='ignore'))
print(f"Parsed {len(ct)} complex numbers.")

# Each block has 256 complex numbers, because NQUBITS=8 -> 2^8 = 256.
n_blocks = len(ct) // 256
print(f"Number of blocks: {n_blocks}")

blocks = []
for i in range(n_blocks):
    blocks.append(ct[i*256 : (i+1)*256])

# Notice that `ct` is generated by encrypting the FLAG.
# FLAG starts with 'TRX{' which is 4 bytes.
# Wait, each block of 256 elements corresponds to an 8-qubit statevector.
# So one block = one byte.

import string

print("Flag starts with 'TRX{'. Let's check if there are repeated blocks.")

same_blocks = {}
for i in range(len(blocks)):
    for j in range(i+1, len(blocks)):
        if np.allclose(blocks[i], blocks[j]):
            if i not in same_blocks:
                same_blocks[i] = []
            same_blocks[i].append(j)
print("Same blocks:", same_blocks)
